[Form]
public class GUPAutoChargePriceAttributeGroupEdit extends FormRun
{
    private MarkupAutoTable callerRecord;
    private GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;
    private GUPPricingRuleCopy pricingRuleCopyHeader;
    private GUPPricingRuleCopy pricingRuleCopyLine;

}

/// <summary>
/// Perform actions at form init
/// </summary>
public void init()
{
    if (!element.args().record() || element.args().dataset() != tableNum(MarkupAutoTable))
    {
        throw error(error::wrongUseOfFunction(funcName()));
    }

    element.initPricingRule();

    super();

    element.enableControls();
}

/// <summary>
/// Initialize pricing rule for auto charge depending on source level
/// </summary>
public void initPricingRule()
{
    callerRecord = element.args().record();
    groupCombination = GUPPriceComponentCodePriceAttributeGroupCombination::find(callerRecord.PriceAttributeGroupCombinationRecId);

    if (!callerRecord.PricingRuleHeader || !this.checkGroupCombinationMatch(groupCombination, callerRecord.PricingRuleHeader, true))
    {
        callerRecord.setPricingRuleReference(fieldNum(MarkupAutoTable, PricingRuleHeader), GUPPricingRule::createRule(groupCombination.HeaderPriceAttributeGroupName).RecId);
    }

    if (!callerRecord.PricingRuleLine || !this.checkGroupCombinationMatch(groupCombination, callerRecord.PricingRuleLine, false))
    {
        callerRecord.setPricingRuleReference(fieldNum(MarkupAutoTable, PricingRuleLine), GUPPricingRule::createRule(groupCombination.LinePriceAttributeGroupName).RecId);
    }

    pricingRuleCopyHeader.initFromPricingRule(GUPPricingRule::find(callerRecord.PricingRuleHeader));
    pricingRuleCopyLine.initFromPricingRule(GUPPricingRule::find(callerRecord.PricingRuleLine));

    callerRecord.dataSource().research(true);
}

/// <summary>
/// Enable/disable controls
/// </summary>
private void enableControls()
{
    boolean allowEditHeader = groupCombination.HeaderGroupAll == GUPGroupAll::Group;
    boolean allowEditLine = groupCombination.LineGroupAll == GUPGroupAll::Group;

    GUPPricingRuleConditionCopyHeader_ds.allowEdit(allowEditHeader);
    PricingRuleConditionsHeader.visible(allowEditHeader);
    GUPPriceDiscPricingRulePreview.visible(allowEditHeader);

    GUPPricingRuleConditionCopyLine_ds.allowEdit(allowEditLine);
    PricingRuleConditionsLine.visible(allowEditLine);
    GUPPriceDiscPricingRulePreviewLine.visible(allowEditLine);
}

/// <summary>
/// Research parent record when closing
/// </summary>
public void close()
{
    super();

    callerRecord.dataSource().research(true);
}

private void refreshPricingRuleCopy()
{
    pricingRuleCopyHeader = GUPPricingRuleCopy::findByRuleId(callerRecord.PricingRuleHeader, true);
    pricingRuleCopyLine = GUPPricingRuleCopy::findByRuleId(callerRecord.PricingRuleLine, true);
}

private boolean checkGroupCombinationMatch(GUPPriceComponentCodePriceAttributeGroupCombination _groupCombination, RefRecId _ruleId, boolean _headerRule)
{
    GUPPricingRule pricingRule;
    select firstonly pricingRule where pricingRule.RecId == _ruleId;
    return (_headerRule && pricingRule.PriceAttributeGroupName == _groupCombination.HeaderPriceAttributeGroupName) ||
        (!_headerRule && pricingRule.PriceAttributeGroupName == _groupCombination.LinePriceAttributeGroupName);
}

public void closeOk()
{
    if (!MarkupAutoTable.PriceAttributeGroupCombinationRecId)
    {
        checkFailed(strFmt("@GlobalUnifiedPricing:GUPDoesNotSelectPriceAttributeGroupCombination"));
    }
    else
    {
        ttsbegin;

        this.refreshPricingRuleCopy();
        pricingRuleCopyHeader.copyToPricingRule();
        pricingRuleCopyLine.copyToPricingRule();

        ttscommit;
        super();
    }
}

public void init()
{
    super();

    QueryBuildDataSource qbdsMarkupAutoTable = MarkupAutoTable_ds.queryBuildDataSource();

    qbdsMarkupAutoTable.clearDynalinks();
    qbdsMarkupAutoTable.clearLinks();

    qbdsMarkupAutoTable.addDynalink(fieldNum(MarkupAutoTable, RecId), callerRecord, fieldNum(MarkupAutoTable, RecId));
}

public display Name displayPricingAttributeName(GUPPricingRuleConditionCopy _ruleCondition)
{
    return _ruleCondition.priceAttributeLink().AttributeName;
}

public edit Name editPricingRuleConditionValue(boolean _set, GUPPricingRuleConditionCopy _ruleCondition, Name _name)
{
    if (_set)
    {
        ttsbegin;
        _ruleCondition.ConditionValue = GUPPricingAttributeConditionValueHelper::editConditionValue(_name, _ruleCondition.ConditionValue, Checkbox_AppendValueOnLookupHeader.checked(), _ruleCondition.priceAttributeLink());
        _ruleCondition.write();
        element.refreshPricingRuleCopy();
        pricingRuleCopyHeader.clearRuleExclusions();

        ttscommit;
    }

    return GUPPricingAttributeAllowedValueLookup::getPriceAttributeValue(
        _ruleCondition.priceAttributeLink().AttributeName,
        _ruleCondition.ConditionValue,
        _ruleCondition.priceAttributeLink());
}

public void init()
{
    super();

    GUPPricingRuleConditionCopyHeader_ds.queryBuildDataSource().addRange(fieldNum(GUPPricingRuleConditionCopy, RuleId)).value(queryValue(callerRecord.PricingRuleHeader));
}

public display Name displayPricingAttributeName(GUPPricingRuleConditionCopy _ruleCondition)
{
    return _ruleCondition.priceAttributeLink().AttributeName;
}

        public edit Name editPricingRuleConditionValue(boolean _set, GUPPricingRuleConditionCopy _ruleCondition, Name _name)
        {
            if (_set)
            {
				ttsbegin;
                _ruleCondition.ConditionValue = GUPPricingAttributeConditionValueHelper::editConditionValue(_name, _ruleCondition.ConditionValue, Checkbox_AppendValueOnLookupLine.checked(), _ruleCondition.priceAttributeLink());
                _ruleCondition.write();

				element.refreshPricingRuleCopy();
                pricingRuleCopyLine.clearRuleExclusions();
                pricingRuleCopyLine.ExclusionType = GUPPricingRuleExclusionType::Product;
                pricingRuleCopyLine.update();

				ttscommit;

            }

            return GUPPricingAttributeAllowedValueLookup::getPriceAttributeValue(
                _ruleCondition.priceAttributeLink().AttributeName,
                _ruleCondition.ConditionValue,
                _ruleCondition.priceAttributeLink());
        }

public void init()
{
    super();

    GUPPricingRuleConditionCopyLine_ds.queryBuildDataSource().addRange(fieldNum(GUPPricingRuleConditionCopy, RuleId)).value(queryValue(callerRecord.PricingRuleLine));
}

public void init()
{
    super();

    QueryBuildDataSource qbdsPricingRule = GUPPricingRuleCopyHeader_ds.queryBuildDataSource();

    qbdsPricingRule.clearLinks();
    qbdsPricingRule.clearDynalinks();

    qbdsPricingRule.addDynalink(fieldNum(GUPPricingRuleCopy, RuleId), callerRecord, fieldNum(MarkupAutoTable, PricingRuleHeader));
}

public void init()
{
    super();

    QueryBuildDataSource qbdsPricingRule = GUPPricingRuleCopyLine_ds.queryBuildDataSource();

    qbdsPricingRule.clearLinks();
    qbdsPricingRule.clearDynalinks();

    qbdsPricingRule.addDynalink(fieldNum(GUPPricingRuleCopy, RuleId), callerRecord, fieldNum(MarkupAutoTable, PricingRuleLine));
}

public Common lookupReference()
{
    SysReferenceTableLookup sysReferenceTableLookup;
    Query                   query = new Query();
    QueryBuildDataSource    qbdsGroupCombination = query.addDataSource(tableNum(GUPPriceComponentCodePriceAttributeGroupCombination));

    sysReferenceTableLookup = SysReferenceTableLookup::newParameters(tableNum(GUPPriceComponentCodePriceAttributeGroupCombination), this);
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, PriceComponentCodeName));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, Name));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderGroupAll));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, HeaderPriceAttributeGroupName));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, LineGroupAll));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, LinePriceAttributeGroupName));
    sysReferenceTableLookup.addLookupfield(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, Priority));

    qbdsGroupCombination.addRange(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, PriceComponentCodeName))
                        .value(any2Str(MarkupAutoTable.PriceComponentCodeName));

    if (MarkupAutoTable.ModuleCategory == HeadingLine::Heading)
    {
        qbdsGroupCombination.addRange(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, LineGroupAll))
                            .value(enum2Symbol(enumNum(GUPGroupAll), GUPGroupAll::All));
    }

    qbdsGroupCombination.addOrderByField(fieldNum(GUPPriceComponentCodePriceAttributeGroupCombination, Priority), SortOrder::Descending);

    sysReferenceTableLookup.parmQuery(query);

    return sysReferenceTableLookup.performFormLookup();
}

public boolean modified()
{
    boolean ret;

    ret = super();

    groupCombination = GUPPriceComponentCodePriceAttributeGroupCombination::find(MarkupAutoTable.PriceAttributeGroupCombinationRecId);

    element.refreshPricingRuleCopy();
    pricingRuleCopyHeader.initPricingRuleCopy(GUPPricingAttributeGroup::findByName(groupCombination.HeaderPriceAttributeGroupName));
    pricingRuleCopyLine.initPricingRuleCopy(GUPPricingAttributeGroup::findByName(groupCombination.LinePriceAttributeGroupName));

    element.enableControls();

    MarkupAutoTable.PricingGroupCodeHeader = groupCombination.HeaderGroupAll;
    MarkupAutoTable.PricingGroupCodeLine = groupCombination.LineGroupAll;
    MarkupAutoTable_ds.research(true);

    GUPPricingRuleConditionCopyHeader_ds.executeQuery();
    GUPPricingRuleConditionCopyLine_ds.executeQuery();

    return ret;
}

        public void lookup()
        {
			GUPPricingAttributeAllowedValueLookup::doLookUp(this, GUPPricingRuleConditionCopyHeader.priceAttributeLink());

